//! Private optional-runtime controls. Discovery does not enable a public target.
#[cfg(target_os="macos")]
fn run()->Result<(),Box<dyn std::error::Error>>{
 use kelft_wasi::{macos_supervisor::{self,Host,Limits},macos_filesystem_session::Grant,native_target::Target,native_resources::EngineContract};use std::{fs,io::Read,path::Path};use sha2::{Digest,Sha256};
 let args=std::env::args().skip(1).collect::<Vec<_>>();if macos_supervisor::helper(&args)?.is_some(){return Ok(());}if args.len()<7||args[5]!="--"||!matches!(args[0].as_str(),"javascript"|"wasm"){return Err("expected ENGINE RUNTIME SHA256 ADAPTER|- PROGRAM -- PROJECT ARGS".into());}
 let read=|path:&Path,maximum:u64|->Result<Vec<u8>,Box<dyn std::error::Error>>{let mut file=fs::File::open(path)?;if !file.metadata()?.is_file()||file.metadata()?.len()>maximum{return Err("bounded engine input required".into());}let mut bytes=vec![];Read::by_ref(&mut file).take(maximum+1).read_to_end(&mut bytes)?;Ok(bytes)};
 let base=fs::canonicalize(std::env::temp_dir())?;let helper=read(&std::env::current_exe()?,64<<20)?;let helper_hash=format!("sha256:{:x}",Sha256::digest(&helper));let host=Host::new(&helper,&helper_hash,&base)?;let runtime=read(Path::new(&args[1]),256<<20)?;let program=read(Path::new(&args[4]),64<<20)?;let adapter=if args[0]=="javascript"{let bytes=read(Path::new(&args[3]),1<<20)?;let hash=format!("sha256:{:x}",Sha256::digest(&bytes));Some((bytes,hash))}else{if args[3]!="-"{return Err("unexpected Wasm adapter".into());}None};
 let project=fs::canonicalize(&args[6])?;let grants=[Grant{guest:"/project/data".into(),path:project.join("data"),read:true,write:false},Grant{guest:"/project/writable".into(),path:project.join("writable"),read:false,write:true}];let result=kelft_wasi::macos_engine::run(&host,&runtime,&args[2],&args[0],adapter.as_ref().map(|(bytes,hash)|(bytes.as_slice(),hash.as_str())),&program,&args[7..],&grants,&base,Limits{wall_ms:15000,output_bytes:65536},&[])?;
 println!("{}",serde_json::json!({"schema":"kelft-native-engine-broker-development/1","profile":Target::current()?.id(),"engine":args[0],"exit":result.exit,"stdout":String::from_utf8_lossy(&result.stdout),"stderr":String::from_utf8_lossy(&result.stderr),"failure":result.failure,"usage":result.usage,"elapsedMs":result.elapsed_ms,"resourceContract":EngineContract::for_engine(Target::current()?,&args[0])?,"filesystemBrokerIntegrated":true,"installedEngineProfileVerified":false,"certified":false,"releaseEligible":false}));Ok(())
}
#[cfg(target_os="macos")]fn main(){if let Err(error)=run(){eprintln!("error[K0600]: {error}");std::process::exit(125);}}
#[cfg(not(target_os="macos"))]fn main(){eprintln!("native macOS host required");std::process::exit(125);}
